"""Evidence-linked HTML; no raw universe files or credentials in the report."""
import argparse,json,pathlib,html
import pandas as pd
def esc(v):return html.escape(str(v))
def tab(f,cols,pct=(),scale=None):
 scale=scale or {};rows=[]
 for r in f.to_dict('records'):
  cells=[]
  for k,label in cols:
   v=r.get(k)
   if v is None or pd.isna(v):s='—'
   elif k in pct:s=f'{float(v)*100:,.2f}%'
   elif isinstance(v,(float,int)) and not isinstance(v,bool):s=f'{float(v)/scale.get(k,1):,.2f}' if k in scale or not float(v).is_integer() else f'{int(v):,}'
   else:s=str(v)
   cells.append('<td>'+esc(s)+'</td>')
  rows.append('<tr>'+''.join(cells)+'</tr>')
 return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+esc(v)+'</th>' for k,v in cols)+'</tr></thead><tbody>'+''.join(rows)+'</tbody></table></div>'
CSS='''body{font:16px/1.7 system-ui,sans-serif;color:#1c2c3c;max-width:1180px;margin:36px auto;padding:0 24px;background:#f8fafc}h1{font-size:30px;line-height:1.35}h2{margin-top:42px;border-bottom:2px solid #b5c9dc;padding-bottom:8px}h3{margin-top:28px}.lead{background:#e9f1fb;border-left:5px solid #37658c;padding:18px}.warn{background:#fff1d8;border-left:5px solid #b88531;padding:16px}.small{font-size:13px;color:#53677a}.scroll{overflow:auto;margin:16px 0}table{width:100%;border-collapse:collapse;background:white;font-size:13px}th,td{padding:8px 10px;border-bottom:1px solid #dce4ec;text-align:right;white-space:nowrap}th{background:#e9eff6}th:first-child,td:first-child{text-align:left}code{font-size:12px;overflow-wrap:anywhere}pre{background:#eaf0f6;padding:15px;white-space:pre-wrap}a{color:#215b92}.hash{font-size:11px;overflow-wrap:anywhere}@media print{body{background:white}tr{break-inside:avoid}}'''
LABELS={'baseline':'기준안','hi9_h3':'9+ · 3일 청산','hi9_h5':'9+ · 5일 청산','hi9_h10':'9+ · 10일 청산','hi9_t5':'9+ · 트레일 5%','hi9_t8':'9+ · 트레일 8%','hi9_t10':'9+ · 트레일 10%','hi9_t8_arm3':'9+ · +3% 후 트레일 8%','hi9_h5_t8':'9+ · 5일+트레일 8%','all_t8':'전체 진입 · 트레일 8%','gate_stop':'20일선 아래 매수 중단','gate_cap5':'20일선 아래 보유 5종목 제한','gate_cap10':'20일선 아래 보유 10종목 제한','hi9_t8_gate_cap10':'9+ 트레일 8% + 10종목 게이트','hi9_replace_up90_t8':'9+ · 기존 익절→트레일 8%','hi9_replace_up90_h5':'9+ · 기존 익절→5일 청산'}
def label(f):
 f=f.copy();f['condition']=f.variant.map(LABELS);return f
def ordered(f,names):
 f=f[f.variant.isin(names)].copy();f['sort']=f.variant.map({n:i for i,n in enumerate(names)});return f.sort_values(['sort']+(['fee_oneway'] if 'fee_oneway' in f else []))
def main():
 p=argparse.ArgumentParser();p.add_argument('--workspace',type=pathlib.Path,required=True);p.add_argument('--output',type=pathlib.Path,required=True);a=p.parse_args();W=a.workspace;O=a.output;O.mkdir(parents=True,exist_ok=True);R=W/'runs';prov=json.loads((O/'SOURCE_PROVENANCE.json').read_text());proto=json.loads((W/'cloudtrend-r4/research/kosdaq_r4/protocol.json').read_text());read=lambda d,n:pd.read_csv(R/d/n);C=read('kosdaq-r4-strict-analysis','account_comparison.csv');L=C[C.scope.eq('long')];N=C[C.scope.eq('recent')];T=read('kosdaq-r4-recent','ticket_comparison.csv');E=read('kosdaq-r4E-analysis','account_comparison.csv');TE=read('kosdaq-r4E-recent','ticket_comparison.csv');F=read('kosdaq-r4-ticket-fixed','fixed_ticket_summary.csv');P=read('kosdaq-r4-strict-analysis','fixed_original_entry_exit_summary.csv');AE=read('kosdaq-r4E-analysis','fixed_original_entry_exit_summary.csv');fee=lambda f:f[f.fee_oneway.eq(.0015)];row=lambda f,n:f[f.variant.eq(n)].iloc[0];pct=lambda x:f'{x*100:,.2f}%';m=lambda x:f'{x/10000:,.2f}만 원';names=[r['name'] for r in proto['variants']];exits=names[:10];gates=['baseline','gate_stop','gate_cap5','gate_cap10','hi9_t8_gate_cap10'];base=row(fee(L),'baseline');cap=row(fee(L),'gate_cap10');recent=row(fee(N),'baseline');risk=read('kosdaq-r4-supplement','risk_measures.csv');risk=risk[risk['mode'].eq('strict')&risk.scope.eq('long')&risk.fee_oneway.eq(.0015)]
 body='''<h1>CloudTrend 코스닥 추가 연구 R4</h1><p class="small">2026-11-08 KST · 9점 이상 진입 허용 + 청산 방식 / 실제 코스닥지수 SMA20 신규매수 게이트</p><div class="lead"><b>결론: 빠른 청산은 최근 손실을 줄였지만 장기 성장률도 낮췄습니다.</b> 시장 게이트는 낙폭을 줄이는 효과가 있었고, 10종목 제한은 수익 감소를 비교적 적게 감수한 방안이었습니다. 현재는 위험관리 후보로 남기며 운영에 적용하지 않았습니다.</div>'''
 body+=f'<p>주표는 합성 가격 청산을 제거하고 관측된 거래 가능 가격으로 체결한 결과입니다. 기준 장기 CAGR <b>{pct(base.cagr)}</b>, MDD <b>{pct(base.mdd)}</b>에서 10종목 제한은 CAGR <b>{pct(cap.cagr)}</b>, MDD <b>{pct(cap.mdd)}</b>로 바뀝니다. 최근 공식 계좌 창은 보유 수가 10종목에 미치지 않아 해당 제한의 손익 효과가 없습니다.</p>'
 body+='''<h2>1. 실험 정의와 비교 범위</h2><p>사전 명세는 14조건입니다. 9점 이상 진입을 일괄 제외하지 않고 원래 Onset 진입을 유지했습니다. 주요 조건은 5일 청산·8% 트레일링·신규매수 중단·10종목 제한이며, 3/10일·5/10%·5종목은 민감도입니다. 최고 수익 조합을 찾는 전체 조합 탐색은 하지 않았습니다.</p>'''
 defs=pd.DataFrame([['고득점 대상','진입 신호일의 저장 기술점수 ≥9.0; 진입 후 점수로 대상을 바꾸지 않음'],['보유일수 청산','진입일을 1일로 한 3·5·10번째 시장 거래일 종가 후 청산 신호 → 이후 관측된 거래 가능 시가'],['트레일링','max(진입 시가, 진입 후 관측 종가) 대비 −5/−8/−10%; 종가 1회 확인 후 다음 거래 가능 시가'],['이익 보호 구분','일반 트레일링과 +3% 상승을 거친 뒤 발동하는 트레일링 8%를 별도로 비교'],['원래 청산과의 관계','주 실험은 원래 UP90·DOWN30·H60와 추가 규칙 중 먼저 실행되는 청산'],['시장 기준','실제 KOSDAQ 지수 종가의 20거래일 단순이동평균; ETF 대용값·20일 수익률을 사용하지 않음'],['게이트 시점','체결 직전 마지막 완료 거래일의 close < SMA20. 체결 당일 종가는 사용하지 않음'],['종목 수 제한','약세일 신규 매수 직전 보유 중인 서로 다른 종목을 최대 5/10개로 제한. 기존 보유분 강제 매도 없음'],['금액·우선순위','30슬롯, 동일 섹터 6슬롯, 전년 말 NAV/30 예산 유지. 제한한 종목의 예산을 다른 종목에 증액하지 않음'],['거절 주문','게이트로 막힌 해당 Onset는 취소; 시장이 좋아졌다고 옛 주문을 자동 매수하지 않음'],['비용','편도 0.15/0.30%, 명목 왕복 0.30/0.60%; 열린 거래는 매도 수수료 없이 기말 평가']],columns=['item','rule']);body+=tab(defs,[('item','항목'),('rule','정의')]);body+='''<p>최고점은 장중 고가가 아닌 관측 종가입니다. 손절선을 건너뛴 시가 갭은 실제 다음 관측 시가로 체결하므로 트레일링 8%가 최대 손실 8%를 보장하지 않습니다. 실제 코스피 K4는 취득원가 대비 −8% 규칙이며, 이번 최고 종가 트레일링은 별도의 연구 규칙으로 정의했습니다.</p>'''
 scope=pd.DataFrame([['최근 동일 금액 신호 재생','2026/9/7–11/6','1회 100만 원, 소수 수량, 원래 26건; 현금·섹터 제한 전 신호 모형'],['최근 공식 계좌','2026/10/14–11/6','현금 3,000만 원 시작, 정수 수량·현금·슬롯·섹터 제약'],['장기 공식 계좌','2017/8/21–2026/9/11','현금 1억 원, 기존 고정 원천 325종목; PIT 미인증'],['시간 가용성 민감도','최근 같은 가격 구간','현재 확보 저장 시각 이후 첫 관측 시가만 허용; 최초 웹 게시 시각과는 구분']],columns=['model','period','unit']);body+=tab(scope,[('model','모형'),('period','범위'),('unit','단위·배정')]);body+='''<p class="warn">한국 9/8·9/14 신호 이력 공백, 10/26 잠정 청산 부분 복구, 11/6 전략 신호 미완성은 유지했습니다. 가격 평가는 11/6까지입니다. 이 구간은 모두 기존에 사용한 자료이며 최근과 장기 끝부분도 일부 겹칩니다. 독립 OOS 또는 실제 투자자 계좌 수익률로 부르지 않습니다.</p>'''
 body+='''<h2>2. 기준선 재현과 결측 체결 규칙</h2><p>기존 R3 장기 기준안의 8개 경제 산출물은 비용 두 수준에서 바이트까지 재현했습니다. 최근 공식 계좌의 NAV·거래·현금도 일치했습니다. 그러나 기존 장기 기준안에는 거래량 0/미관측 때 전일 시가로 처리한 <b>모델 청산 14건</b>이 포함돼 있었습니다.</p><p>원래 비교를 보존한 채 이 예외만 연구용 복사본에서 제거했습니다. 연도별 배정과 UP90·DOWN30·H60는 유지하고 실제 거래 가능 가격이 나올 때까지 포지션과 주문을 보존했습니다. 추가 후보나 임계값을 바꾸지 않고 14조건 전체·두 비용을 다시 비교했습니다.</p>'''
 definition=read('kosdaq-r4-supplement','execution_definition_sensitivity.csv');body+=tab(definition[definition.scope.eq('long')&definition.variant.eq('baseline')],[('fee_oneway','편도 비용'),('legacy_cagr','기존 모델 CAGR'),('strict_cagr','관측 체결 CAGR'),('legacy_mdd','기존 MDD'),('strict_mdd','관측 체결 MDD'),('legacy_proxy_exits','기존 모델 청산'),('strict_proxy_exits','관측 모형 합성 청산')],['fee_oneway','legacy_cagr','strict_cagr','legacy_mdd','strict_mdd']);body+='''<p>이 때문에 이전의 22.09%와 이번 주표의 기준선은 다릅니다. 비교는 각 자료 처리 방식 안에서 같은 입력·예산·체결·비용으로 수행했습니다. 관측 체결 기준에서는 기준안의 거래량 0인 보유 평가일 76건을 보유 상태로 유지했습니다. 원천이 제공한 마지막 가격은 평가에 사용하고 해당 가격으로 매도하지 않았습니다. 기말 미청산 5종목은 남겨 평가했으며 해당 일자의 가격과 양의 거래량이 존재했습니다.</p>'''
 body+='''<h2>3. 테스트 A — 9점 이상 진입분의 추가 청산</h2><p><b>최근 손실 완화는 확인했지만 장기 수익 개선은 확인하지 못했습니다.</b> 아래는 왕복 0.30%, 관측 체결 기준 장기 계좌입니다. 9점 미만 진입의 청산은 원래대로 유지했습니다.</p>'''
 cols=[('condition','조건'),('n','거래 수'),('cagr','CAGR'),('mdd','MDD'),('avg_exposure','평균 노출'),('turnover_gross_over_initial','누적 회전/초기자본'),('high9_entries','9점 이상 진입')];body+=tab(label(ordered(fee(L),exits)),cols,['cagr','mdd','avg_exposure']);body+='''<p>3·5일로 짧게 줄인 규칙은 장기 MDD도 오히려 악화했습니다. 8% 트레일링도 같은 문제가 있었고, 이익 보호를 +3% 이후에 켜거나 10%로 넓힌 경우에도 기준 성장률을 넘지 못했습니다. 전 종목에 8% 트레일링을 적용한 대조군은 더 큰 수익 감소를 보였습니다.</p><h3>같은 원래 진입 1,039건을 고정한 비교</h3>''';fx=fee(P[P.scope.eq('long')&P.cohort.eq('high9')]);body+=tab(label(ordered(fx,exits)),[('condition','9점 이상 원래 진입'),('n','고정 거래 수'),('mean_return','평균 수익률'),('median_return','중앙값'),('win_rate','승률'),('mean_delta','기준 대비 평균 변화'),('mean_mae','평균 MAE'),('mean_mfe','평균 MFE')],['mean_return','median_return','win_rate','mean_delta','mean_mae','mean_mfe']);body+='''<p>청산만 바꾸면 새 진입의 평균 수익률이 좋아진다는 근거도 없었습니다. 이후 다른 신호에 현금과 슬롯을 다시 배정하는 전체 계좌와, 원래 진입·원래 금액을 고정한 위 표를 구분했습니다. 재진입으로 늘어난 거래는 원래 거래 개선으로 세지 않았습니다.</p><h3>최근 전체 원래 26건 중 9점 이상 11건</h3>''';fx=fee(F[F.cohort.eq('high9')]);body+=tab(label(ordered(fx,exits)),[('condition','청산 조건'),('n','원래 기회 고정'),('pnl','손익, 만 원'),('delta_pnl','기준 대비, 만 원'),('mean_return','평균')],['mean_return'],{'pnl':10000,'delta_pnl':10000});body+='''<p>최근에는 손실을 상당히 줄였습니다. 하지만 장기에서 이익을 내던 고득점 거래의 상승 구간도 잘라냈습니다. 신규 진입을 다시 허용하는 전체 재생에서는 추가 거래 손익이 더해지므로 이 고정 11건 표보다 결과가 나빠질 수 있습니다.</p>'''
 body+='''<h3>기존 익절을 교체하는 별도 탐색</h3><p>고득점 원래 장기 거래 1,039건 중 499건은 기존 UP90 익절로 끝났습니다. 따라서 추가 청산과 구분해, 9점 이상 진입의 UP90만 8% 트레일링 또는 5일 청산으로 교체하는 실험도 수행했습니다. DOWN30·H60와 9점 미만 청산은 보존했습니다. 이 두 조건은 주 실험 결과 확인 후 정한 별도 탐색이며, 임계값 8%와 5일은 기존 사전 명세 값을 그대로 사용했습니다.</p>''';body+=tab(label(ordered(fee(E[E.scope.eq('long')]),['baseline','hi9_replace_up90_t8','hi9_replace_up90_h5'])),cols,['cagr','mdd','avg_exposure']);body+='''<p>익절 교체 역시 장기 기준 성장률을 넘지 못했습니다. 추가 청산 때문에 효과가 가려진 것만으로 이번 결과를 설명할 수 없습니다. 이 탐색도 채택 후보로 확정하지 않았습니다.</p>'''
 body+='''<h2>4. 테스트 B — 코스닥 20일선 신규매수 게이트</h2><p><b>시장 게이트는 수익 증대보다 노출·낙폭 관리의 효과가 컸습니다.</b> 20일선 위에서는 기존 30슬롯을 유지하고, 아래에서는 신규매수를 중단하거나 보유 종목 수만 제한했습니다.</p>''';body+=tab(label(ordered(fee(L),gates)),cols,['cagr','mdd','avg_exposure']);r=fee(N);body+='<h3>최근 공식 계좌의 실제 제약 효과</h3>';body+=tab(label(ordered(r,gates)),[('condition','조건'),('n','거래 수'),('nav_return','계좌 수익률'),('mdd','MDD'),('avg_exposure','평균 노출'),('avg_cash','평균 현금'),('gate_rejections','게이트 거절')],['nav_return','mdd','avg_exposure','avg_cash']);body+='''<p>최근 공통 창은 지수가 계속 20일선 아래여서 매수 중단 계좌는 신규 거래가 0건입니다. 따라서 0%는 현금을 보유한 결과입니다. 5종목 제한은 손실을 줄였지만 10종목 제한은 당시 보유 수가 한도에 미치지 않아 효과가 없었습니다. 기존 보유분의 하락을 새 매수 게이트가 직접 청산해 막는 구조는 아닙니다.</p><h3>같은 노출의 기준안+현금 대조</h3>''';ct=read('kosdaq-r4-strict-analysis','same_exposure_cash_control.csv');body+=tab(label(ordered(ct[ct.scope.eq('long')],['gate_stop','gate_cap5','gate_cap10'])),[('condition','조건'),('fee_oneway','편도 비용'),('cagr','같은 노출 대조 CAGR'),('candidate_cagr','조건 CAGR'),('candidate_mdd','조건 MDD')],['fee_oneway','cagr','candidate_cagr','candidate_mdd']);body+='''<p>대조는 사후에 평균 노출을 맞춘 기준안과 무이자 현금의 상수 비중 혼합입니다. 미래 비중을 알고 매매하는 전략이 아닙니다. 10종목 제한은 이 대조보다 CAGR이 약 0.09%p 높았고 두 비용에서도 같은 방향이었지만 차이가 작았습니다. 이를 검증된 새로운 초과수익으로 채택하지 않았습니다.</p>''';body+=tab(label(ordered(risk,['baseline','gate_stop','gate_cap5','gate_cap10'])),[('condition','조건'),('sharpe_zero_rf','Sharpe'),('calmar','Calmar')]);body+='''<p class="small">Sharpe는 일별 수익률·연 252세션·무위험수익률 0의 비교 지표입니다. Calmar는 경과일 기준 CAGR/장기 MDD 절댓값입니다. 10종목 제한의 위험 대비 효율은 소폭 좋아졌지만 과거 재사용 자료의 기술 통계입니다.</p><h3>연도별 연속 계좌</h3>''';yr=read('kosdaq-r4-strict-analysis','annual_continuous_account.csv');yr=yr[yr.fee_oneway.eq(.0015)&yr.variant.isin(['baseline','hi9_h5','hi9_t8','gate_stop','gate_cap10'])].pivot(index='year',columns='variant',values='nav_return').reset_index();body+=tab(yr,[('year','연도'),('baseline','기준'),('hi9_h5','9+ H5'),('hi9_t8','9+ 트레일 8%'),('gate_stop','매수 중단'),('gate_cap10','10종목 제한')],['baseline','hi9_h5','hi9_t8','gate_stop','gate_cap10']);body+='''<p>연도마다 최고 조건을 고르거나 계좌를 초기화하지 않았습니다. 2020·2022·2026처럼 방어 게이트가 유리한 조각이 있는 반면 2018·2024·2025에서는 수익을 더 놓쳤습니다. 2017·2026은 부분 연도이며, 연도 표는 워크포워드 최적화나 독립 OOS가 아닙니다.</p>'''
 body+='''<h2>5. 최근 재생·배정 변화·비용 민감도</h2><p>아래 손익은 최근 전체 신호에 회당 100만 원을 배정한 합계입니다. 현금·슬롯·섹터를 적용한 계좌 수익률과 단위가 다릅니다. 저장 시각 열은 현재 확보 저장본의 시각 이후 첫 시가만 사용한 보수적 민감도로, 당시 최초 웹 게시 시각을 인증한 실제 성과는 아닙니다.</p>''';t=fee(T).pivot(index='variant',columns='clock',values='pnl').reset_index().rename(columns={'logical':'logical_pnl','retained_save_time':'available_pnl'});body+=tab(label(ordered(t,names)),[('condition','조건'),('logical_pnl','논리 신호일 손익, 만 원'),('available_pnl','저장시각 이후 손익, 만 원')],scale={'logical_pnl':10000,'available_pnl':10000});body+='''<h3>최근 원래 진입·새 진입 경로 분리</h3>''';bridge=read('kosdaq-r4-strict-analysis','entry_path_bridge.csv');body+=tab(label(ordered(fee(bridge[bridge.scope.eq('recent')]),['hi9_h5','hi9_t8','gate_stop','gate_cap5','gate_cap10'])),[('condition','조건'),('common','같은 진입'),('removed','제외 진입'),('new','새 진입'),('same_entry_effect','같은 진입 변화, 만 원'),('avoided_effect','제외 효과, 만 원'),('new_entry_effect','새 진입 손익, 만 원')],scale={k:10000 for k in ['same_entry_effect','avoided_effect','new_entry_effect']});body+='''<p>장기 같은 진입 금액의 차이에는 연도별 NAV 예산 변화도 포함되므로, 순수 청산 선택 효과는 고정 원래 진입의 평균 수익률 표에서 따로 확인했습니다. 새 진입을 단순히 원래 손실 거래의 개선으로 합산하지 않았습니다.</p><h3>장기 두 비용 전체 표</h3>''';body+=tab(label(ordered(L,names)),[('condition','조건'),('fee_oneway','편도 비용'),('n','거래 수'),('cagr','CAGR'),('mdd','MDD'),('avg_exposure','평균 노출'),('mean_return','평균 거래'),('median_return','중앙값'),('win_rate','승률'),('payoff_ratio','손익비'),('mean_mae','평균 MAE'),('mean_mfe','평균 MFE')],['fee_oneway','cagr','mdd','avg_exposure','mean_return','median_return','win_rate','mean_mae','mean_mfe']);body+='''<p>거래 수와 승률에는 기말 평가 중인 거래가 포함됩니다. MAE/MFE는 보유 종가와 진입·청산 체결가 기준이며, 장중 고저 참고값은 청산일을 일괄 제외한 보수적 정의로 CSV에 남겼습니다. 작은 최근 표본과 같은 종목의 재진입 의존성을 고려해 종목·진입월 군집 1,500회 재표집 구간을 저장했습니다. 이는 재사용 표본의 기술적 구간이며 다중 탐색 뒤의 독립 유의성 주장에 사용하지 않았습니다.</p>'''
 body+='''<h2>6. 후보 판단과 다음 검증</h2>''';dec=pd.DataFrame([['9+ H3/H5/H10','운영 채택 보류','최근 방어 효과 있으나 장기 수익 감소, 일부 MDD 악화'],['9+ 트레일 5/8/10%·이익 보호','운영 채택 보류','상승 거래도 잘라내 장기 평균 고정 진입 수익 하락'],['고득점 UP90 익절 교체','별도 탐색 보류','교체 실험도 기준 장기 성장률 미달; 사후 탐색'],['20일선 아래 매수 중단·5종목 제한','방어 목적의 선택지','최근 방어 강함; 장기 성장·재상승 초반 기회 비용'],['20일선 아래 10종목 제한','후속 검증 우선 후보','장기 MDD·위험 대비 효율 개선과 성장 희생의 균형; 최근 한도 미도달'],['트레일 8%+10종목 제한','운영 채택 보류','각각의 이점을 합쳐도 장기 성과 개선으로 이어지지 않음']],columns=['candidate','decision','why']);body+=tab(dec,[('candidate','후보'),('decision','판단'),('why','근거')]);body+='''<p>새 검증은 11/9 이후 처음 생성되는 신호부터 규칙을 잠가 관찰합니다. 이미 확인한 11/6 신호가 나중에 체결되는 것은 새 OOS 신호로 세지 않습니다. 최소 3개월·공통 신규 기회 40건과 20일선 위아래의 실제 전환을 함께 확인하고, 수익·낙폭·노출·회전·현금·게이트 거절을 같은 비용으로 대조합니다. 중간 결과에 따라 임계값을 바꾸지 않습니다. 이 계획으로 자동매매·알림·운영 변경을 생성하지 않았습니다.</p>'''
 body+='''<h2>7. 코드·원천·검증·재현</h2><p>사전 명세 14조건 × 두 비용 × 장기/최근 × 기존/관측 체결 = 112계좌를 계산했습니다. 별도 익절 교체 탐색은 기준 포함 12계좌입니다. 최근 두 시계 신호모형과 원래 진입 26건 고정 비교도 별도로 수행했습니다. 관측 체결 56계좌와 탐색 12계좌에는 합성 청산이 0건이며, 현금·NAV 독립 재계산 오차는 모두 0입니다.</p><p>실제 코스닥지수는 기존 CM 아카이브·검증된 9월 원천·최근 게시 원천으로 연결했습니다. 누락됐던 9/14–9/21은 단일 보관 ZIP 전체 SHA와 내부 원래 객체 SHA를 확인해 복구했으며 보간하지 않았습니다. 겹친 날짜의 종가가 같고, 11/6 종가 644.27 및 SMA20 758.071이 원래 실행 결과와 일치합니다.</p><p>핵심 회귀검증은 18종입니다. 다음 시가·갭 체결, 진입 점수 대상, 시장 보유일수, 결측일 경과, 최고 종가·이익 보호 발동, 기말 청산 대기, 이전 거래일 시장 상태, 동일 시가 매도 후 한도, 모델 청산 제거, 저점수·하락 청산 보존, 저장 시각·재개를 확인했습니다. Colab은 구문을 검증했고 같은 계산 코드를 로컬에서 실행했습니다.</p>'''
 body+=f'<p>기준 main <code>{esc(prov["main_commit"])}</code><br>R3 코드 <code>{esc(prov["r3_research_commit"])}</code><br>R4 연구 코드 <code>{esc(prov.get("research_commit","PENDING"))}</code><br>브랜치 <code>research/kosdaq-exits-gates-r4-20261108</code><br>실험 <code>kosdaq-exits-gates-r4-20261108</code>, 별도 탐색 <code>kosdaq-exits-gates-r4E-20261108</code></p>'
 body+='''<p>최종 ZIP의 SOURCE_PROVENANCE.json·DELIVERY_MANIFEST.json·protocol*.json·각 COMPLETE.json에 원천 위치·버전·해시·실험 ID·검증 기록을 남겼습니다. 원래 자료와 R3 출력은 보존했습니다. 연구용 복사본의 최소 변경만 적용했으며 운영 수집기·스크리닝·실제 원장·전략 설정을 변경하지 않았습니다.</p><pre>python research/kosdaq_r4/run_all.py --workspace /path/CloudTrend_KOSDAQ_R4_20261108 --run-dir /Drive/new_R4_reproduction --node /path/node24</pre><p>Colab은 Drive에 로그·중간 결과·완료 체크포인트를 저장하고 같은 RUN_ID로 재개합니다. 처리한 과거 입력이나 코드가 바뀌면 이전 체크포인트를 재사용하지 않습니다. 원천 전체·비밀정보는 이 Notion 보고서에 업로드하지 않았습니다.</p>'''
